//! `fb contribute pick|claim|brief|verify|submit`: the one entry point for contributing to formbook, by a human
//! or an agent (was tools/contribute.sh and tools/contribute-lib.sh).
//!
//! A unit of work is one (court, doc type) pair listed in data/worklist.json (generated by `fb worklist`).
//! Its id is "<court alias>.<doctype>", e.g. ca1.amicus-brief. The claim is the remote branch contrib/<id>.
//! kinds: new-template, new-doctype, add-exemplar, deepen. Read-only steps (pick, brief, verify) need no push
//! access. claim and submit push; without write access they fall back to the fork workflow (a draft PR from
//! your fork is the claim). See CONTRIBUTING.md. Needs git; optional gh (PRs, fork),
//! typst + poppler (verify; run tools/bootstrap.sh). CONTRIB_REMOTE and CONTRIB_BASE override origin/master.
mod brief;
mod claimcmd;
mod pick;
mod scan;
mod submit;
mod verify;

use crate::proc::{capture, have};
use crate::{fail, repo_root, Fail, Res};
use serde_json::Value;
use std::collections::BTreeSet;
use std::path::Path;
use std::process::{Command, ExitCode, Output};

pub const USAGE: &str = "\
just contribute pick   [--seed N] [--kind K] [--priority P] [--offline]
just contribute claim  <id> [--dry-run] [--fork] [--no-worktree]
just contribute brief  <id>
just contribute verify <id> [--base REF]
just contribute submit <id> [--dry-run] [--skip-verify] [--base REF]";

const SLUG_DEFAULT: &str = "davidawad/formbook";
const WL: &str = "data/worklist.json";

/// The error `die` raised in the shell version.
pub fn die(msg: impl std::fmt::Display) -> Fail {
    fail(1, format!("fb contribute: {msg}"))
}

pub fn usage() -> Fail {
    fail(2, USAGE)
}

/// Whether a step may talk to the remote.
#[derive(Clone, Copy, PartialEq)]
pub enum Net {
    Online,
    Offline,
}

/// Remote and base branch names, from CONTRIB_REMOTE / CONTRIB_BASE.
pub struct Ctx {
    pub remote: String,
    pub base: String,
}

impl Ctx {
    fn from_env() -> Ctx {
        Ctx {
            remote: std::env::var("CONTRIB_REMOTE").unwrap_or_else(|_| "origin".into()),
            base: std::env::var("CONTRIB_BASE").unwrap_or_else(|_| "master".into()),
        }
    }

    pub fn remote_base(&self) -> String {
        format!("{}/{}", self.remote, self.base)
    }
}

pub fn git(args: &[&str]) -> Res<Output> {
    capture(Command::new("git").args(args))
}

/// Stdout of a git command that exited zero, else None.
pub fn git_out(args: &[&str]) -> Res<Option<String>> {
    let o = git(args)?;
    Ok(o.status
        .success()
        .then(|| String::from_utf8_lossy(&o.stdout).into_owned()))
}

pub fn git_ok(args: &[&str]) -> Res<bool> {
    Ok(git(args)?.status.success())
}

/// `owner/repo` of a GitHub remote URL (ssh or https), else None.
pub fn slug_of(url: &str) -> Option<String> {
    let i = url.rfind("github.com")?;
    let rest = url[i + "github.com".len()..].strip_prefix([':', '/'])?;
    (rest.matches('/').count() == 1).then(|| rest.strip_suffix(".git").unwrap_or(rest).to_string())
}

pub fn repo_slug(ctx: &Ctx) -> Res<String> {
    let url = git_out(&["remote", "get-url", &ctx.remote])?.unwrap_or_default();
    Ok(slug_of(url.trim()).unwrap_or_else(|| SLUG_DEFAULT.to_string()))
}

/// The worklist from origin/master when reachable (so everyone sees the same list), else the local file.
pub fn load_worklist(ctx: &Ctx, net: Net) -> Res<Value> {
    let remote = if net == Net::Offline || !git_ok(&["fetch", "-q", &ctx.remote, &ctx.base])? {
        None
    } else {
        git_out(&["show", &format!("{}:{WL}", ctx.remote_base())])?
    };
    let text = match remote {
        Some(t) => t,
        None => std::fs::read_to_string(WL).map_err(|_| {
            die(format!(
                "no {WL} here and {} is unreachable; run: just worklist",
                ctx.remote_base()
            ))
        })?,
    };
    serde_json::from_str(&text).map_err(|e| die(format!("{WL}: {e}")))
}

pub fn unit_json(wl: &Value, id: &str) -> Option<Value> {
    wl["units"]
        .as_array()?
        .iter()
        .find(|u| u["id"] == id)
        .cloned()
}

pub fn field(u: &Value, key: &str) -> String {
    u[key].as_str().unwrap_or("").to_string()
}

pub fn read_json(path: &str) -> Value {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|t| serde_json::from_str(&t).ok())
        .unwrap_or(Value::Null)
}

/// `min_pages` of a doc type (2 when absent), as jq printed it.
pub fn min_pages(doctype: &str) -> f64 {
    read_json("data/doctypes.json")["doctypes"][doctype]["min_pages"]
        .as_f64()
        .unwrap_or(2.0)
}

/// The unit's current state from the tree on disk: new | new-template | add-exemplar | deepen | complete.
pub fn unit_state(court_path: &str, doctype: &str) -> String {
    let d = Path::new(court_path).join(doctype);
    if !d.is_dir() {
        return "new".into();
    }
    let has =
        |sub: &str, ok: &dyn Fn(&str) -> bool| !crate::worklist::files(d.join(sub), ok).is_empty();
    if !has("typst", &|n| n.ends_with(".typ")) {
        return "new-template".into();
    }
    if !has("usage", &|n| {
        n.starts_with("FILED-EXAMPLE-") && n.ends_with(".pdf")
    }) {
        return "add-exemplar".into();
    }
    let pages = crate::worklist::max_pages(&d);
    if pages > 0 && f64::from(pages) < min_pages(doctype) {
        "deepen"
    } else {
        "complete"
    }
    .into()
}

/// Ids already taken: remote contrib/* branches, remote court/<alias> branches (whole court claimed), and
/// open PR head branches named contrib/* or court/* (fork claims).
#[derive(Default)]
pub struct Claimed {
    pub ids: BTreeSet<String>,
    pub courts: BTreeSet<String>,
}

impl Claimed {
    pub fn add_ref(&mut self, name: &str) {
        if let Some(i) = name.strip_prefix("contrib/") {
            self.ids.insert(i.into());
        } else if let Some(c) = name.strip_prefix("court/") {
            self.courts.insert(c.into());
        }
    }

    pub fn is_claimed(&self, id: &str, alias: &str) -> bool {
        self.ids.contains(id) || self.courts.contains(alias)
    }
}

pub fn claimed_set(ctx: &Ctx, net: Net) -> Res<Claimed> {
    let mut c = Claimed::default();
    if net == Net::Offline {
        return Ok(c);
    }
    let heads = git_out(&[
        "ls-remote",
        "--heads",
        &ctx.remote,
        "refs/heads/contrib/*",
        "refs/heads/court/*",
    ])?
    .unwrap_or_default();
    heads
        .lines()
        .filter_map(|l| l.split_once("refs/heads/").map(|(_, n)| n))
        .for_each(|n| c.add_ref(n));
    if have("gh") {
        let slug = repo_slug(ctx)?;
        let o = capture(Command::new("gh").args([
            "pr",
            "list",
            "--repo",
            &slug,
            "--state",
            "open",
            "--limit",
            "300",
            "--json",
            "headRefName",
            "-q",
            ".[].headRefName",
        ]))?;
        if o.status.success() {
            String::from_utf8_lossy(&o.stdout)
                .lines()
                .for_each(|n| c.add_ref(n));
        }
    }
    Ok(c)
}

pub fn main(args: &[String]) -> Res<ExitCode> {
    let root = repo_root()?;
    std::env::set_current_dir(&root)
        .map_err(|e| fail(2, format!("fb contribute: {}: {e}", root.display())))?;
    let ctx = Ctx::from_env();
    let (sub, rest) = args.split_first().ok_or_else(usage)?;
    match sub.as_str() {
        "pick" => pick::run(&ctx, rest),
        "claim" => claimcmd::run(&ctx, &root, rest),
        "brief" => brief::run(&ctx, rest),
        "verify" => verify::run(&ctx, rest),
        "submit" => submit::run(&ctx, rest),
        _ => Err(usage()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn slug_from_github_urls() {
        assert_eq!(
            slug_of("git@github.com:davidawad/formbook.git").as_deref(),
            Some("davidawad/formbook")
        );
        assert_eq!(slug_of("https://github.com/a/b").as_deref(), Some("a/b"));
        assert_eq!(slug_of("https://gitlab.com/a/b.git"), None);
        assert_eq!(slug_of("https://github.com/a/b/c"), None);
    }

    #[test]
    fn claimed_refs() {
        let mut c = Claimed::default();
        ["contrib/ca1.x", "court/ca2", "feature/z"]
            .iter()
            .for_each(|n| c.add_ref(n));
        assert!(c.is_claimed("ca1.x", "ca1"));
        assert!(c.is_claimed("ca2.y", "ca2"));
        assert!(!c.is_claimed("ca3.y", "ca3"));
    }

    #[test]
    fn unit_lookup() {
        let wl = serde_json::json!({"units": [{"id": "a.b", "kind": "deepen"}]});
        assert_eq!(field(&unit_json(&wl, "a.b").unwrap(), "kind"), "deepen");
        assert!(unit_json(&wl, "zz").is_none());
    }
}
